#!/usr/bin/env python3
"""Render the project-managed chrony drop-in from the validated mission."""

from __future__ import annotations

import argparse
from ipaddress import ip_network
from pathlib import Path

from purdue_rov_cv.config.loader import load_config


def render_chrony(config_path: Path, role: str) -> str:
    config = load_config(config_path, environ={})
    if role == "pi":
        return (
            "# Generated by scripts/configure_chrony.py\n"
            f"server {config.clock.server_ip} iburst minpoll 2 maxpoll 4\n"
            "makestep 0.1 3\n"
            "rtcsync\n"
        )
    if role == "surface":
        subnet = ip_network(f"{config.network.rov_ip}/24", strict=False)
        if config.network.surface_ip not in subnet:
            raise ValueError("V1 surface and ROV addresses must share the configured /24 tether subnet")
        return (
            "# Generated by scripts/configure_chrony.py\n"
            "local stratum 8\n"
            f"allow {subnet}\n"
            f"bindaddress {config.network.surface_ip}\n"
            "makestep 0.1 3\n"
        )
    raise ValueError("role must be pi or surface")


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--config", type=Path, required=True)
    parser.add_argument("--role", choices=("pi", "surface"), required=True)
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    content = render_chrony(args.config, args.role)
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(content, encoding="ascii")
    print(args.output)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
